class Solution {
    public int countKDifference(int[] nums,int k){
        Map<Integer,Integer> frequency=new HashMap<>();
        int answer=0;
        for(int value:nums){
            answer+=frequency.getOrDefault(value-k,0)+frequency.getOrDefault(value+k,0);
            frequency.merge(value,1,Integer::sum);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countKDifference(nums:IntArray,k:Int):Int{
        val frequency=HashMap<Int,Int>();
        var answer=0;
        for(value in nums){
            answer+=(frequency[value-k]?:0)+(frequency[value+k]?:0);
            frequency[value]=(frequency[value]?:0)+1
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int countKDifference(vector<int>& nums,int k){
        unordered_map<int,int> frequency;
        int answer=0;
        for(int value:nums){
            answer+=frequency[value-k]+frequency[value+k];
            ++frequency[value];
        }
        return answer;
    }
};
